using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
class SoundModeControl : Control {
    internal int Index=1;float position=1;Timer slide;internal event EventHandler SelectionChanged;static readonly string[] labels={"끔","이어폰","전체"};
    internal SoundModeControl(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Selectable,true);TabStop=true;AccessibleRole=AccessibleRole.Slider;AccessibleName="효과음 출력 모드";Cursor=Cursors.Hand;AccessibleDescription=labels[Index];}
    internal void SetIndex(int index){index=Math.Max(0,Math.Min(2,index));if(Index==index)return;Index=index;AccessibleDescription=labels[Index];if(!IsHandleCreated||!Visible)position=Index;else{if(slide==null){slide=new Timer{Interval=15};slide.Tick+=(s,e)=>{position+=(Index-position)*.34f;if(Math.Abs(Index-position)<.005f){position=Index;slide.Stop();}Invalidate();};}slide.Start();}Invalidate();}
    protected override void Dispose(bool disposing){if(disposing&&slide!=null)slide.Dispose();base.Dispose(disposing);}
    void Select(int index){SetIndex(index);if(SelectionChanged!=null)SelectionChanged(this,EventArgs.Empty);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left){Focus();Select(e.X*3/Math.Max(1,Width));}}
    protected override bool IsInputKey(Keys keyData){var key=keyData&Keys.KeyCode;return key==Keys.Left||key==Keys.Right||key==Keys.Up||key==Keys.Down||key==Keys.Home||key==Keys.End||key==Keys.PageUp||key==Keys.PageDown||base.IsInputKey(keyData);}
    protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right){Select(Index+(e.KeyCode==Keys.Left?-1:1));e.Handled=true;}else if(e.KeyCode==Keys.Home||e.KeyCode==Keys.End){Select(e.KeyCode==Keys.Home?0:2);e.Handled=true;}else base.OnKeyDown(e);}
    protected override void OnPaint(PaintEventArgs e){PetTheme.PaintUnder(e.Graphics,this);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;using(var shape=SettingArt.Round(new Rectangle(0,0,Width-1,Height-1),12))using(var fill=new SolidBrush(PetTheme.Button))g.FillPath(fill,shape);int w=Width/3;var selected=new Rectangle((int)Math.Round(position*w)+2,2,w-4,Height-5);using(var shape=SettingArt.Round(selected,10))using(var fill=new SolidBrush(PetTheme.Accent))g.FillPath(fill,shape);var flags=TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.NoPadding|TextFormatFlags.PreserveGraphicsClipping;for(int i=0;i<3;i++)TextRenderer.DrawText(g,labels[i],Font,new Rectangle(i*w,0,w,Height),PetTheme.Ink,flags);var state=g.Save();using(var shape=SettingArt.Round(selected,10))g.SetClip(shape,CombineMode.Intersect);for(int i=0;i<3;i++)TextRenderer.DrawText(g,labels[i],Font,new Rectangle(i*w,0,w,Height),PetTheme.SelectionInk,flags);g.Restore(state);if(Focused&&ShowFocusCues)using(var pen=new Pen(PetTheme.Ink,1))using(var shape=SettingArt.Round(new Rectangle(2,2,Width-5,Height-5),7))g.DrawPath(pen,shape);}
}
